  },
  {
    id = 2801001,
    content = "V\195\172 ti\225\186\191ng h\195\161t n\198\161i bi\225\187\131n xa; V\195\172 \196\145\198\176\225\187\157ng h\225\186\167m n\198\161i n\195\186i cao; V\195\172 chi\225\186\191n tranh v\195\160 h\195\178a b\195\172nh; D\197\169ng s\196\169 \196\145\225\187\153i gai l\195\160m m\197\169, kho\195\161c b\225\187\165i r\225\186\173m l\195\160m \195\161o, l\198\176\225\187\155t s\195\179ng m\195\160 \196\145\225\186\191n"
  },
  {
    id = 2801002,
    content = "Ng\225\187\141n l\225\187\173a v\195\160 sao b\196\131ng, k\195\169o \196\145\225\186\191n li\195\170n h\225\187\147i, b\198\176\225\187\155c ch\195\162n ph\225\187\167 kh\225\186\175p b\195\161t ph\198\176\198\161ng, h\198\161i th\225\187\159 nu\225\187\145t tr\225\187\141n t\225\187\169 h\225\186\163i"
  },
  {
    id = 2801003,
    content = "D\225\186\165u ch\195\162n th\195\186 s\195\162u c\225\186\161n, d\225\186\165u v\225\186\191t m\195\170 \225\186\163o, c\195\185ng m\225\187\159 m\195\160n cho m\225\187\153t bu\225\187\149i t\195\160n s\195\161t, ng\198\176\198\161i l\195\160 con m\225\187\147i hay k\225\186\187 \196\145i s\196\131n?"
  },
  {
    id = 2801004,
    content = "B\195\160n ch\195\162n l\225\186\161nh nh\198\176 b\196\131ng, in hoa s\198\176\198\161ng tuy\225\186\191t bay"
  },
  {
    id = 2801005,
    content = "B\198\176\225\187\155c qua r\225\187\171ng hoa nh\225\186\161t, b\198\176\225\187\155m bay kh\195\161ch ch\225\186\179ng hay, \196\145\225\186\161p hoa \196\145i v\225\186\161n d\225\186\183m, b\198\176\225\187\155m lu\195\180n theo b\225\186\167u b\225\186\161n"
  },
  {
    id = 2801006,
    content = "C\198\176\225\187\161i tr\195\170n s\195\179ng bi\225\187\131n, tung ho\195\160nh kh\225\186\175p ch\195\162n tr\225\187\157i"
